function switchCommunityTab(tab) {
  if (tab === "ranking") {
    tabRankingBtn.classList.add("active");
    tabLoungeBtn.classList.remove("active");
    tabRankingBtn.style.borderBottomColor = "var(--text-primary)";
    tabRankingBtn.style.color = "var(--text-primary)";
    tabLoungeBtn.style.borderBottomColor = "transparent";
    tabLoungeBtn.style.color = "var(--text-secondary)";
    rankingTabContent.style.display = "block";
    loungeTabContent.style.display = "none";
    writePostBtn.style.display = "none";
    renderRanking();
  } else {
    tabRankingBtn.classList.remove("active");
    tabLoungeBtn.classList.add("active");
    tabRankingBtn.style.borderBottomColor = "transparent";
    tabRankingBtn.style.color = "var(--text-secondary)";
    tabLoungeBtn.style.borderBottomColor = "var(--text-primary)";
    tabLoungeBtn.style.color = "var(--text-primary)";
    const badge = document.getElementById("lounge-new-badge");
    if (badge) badge.style.display = "none";
    rankingTabContent.style.display = "none";
    loungeTabContent.style.display = "block";
    writePostBtn.style.display = "block";
    renderLoungeFeed();
  }
}
function getUserWritingTier(totalChars) {
  const isEn = typeof currentLang !== "undefined" && currentLang === "en";
  if (totalChars <= 5e3) {
    return {
      name: isEn ? "Sprout Writer \u{1F331}" : "\uC0C8\uC2F9 \uC791\uAC00 \u{1F331}",
      next: 5e3,
      nextName: isEn ? "Neighborhood Writer" : "\uB3D9\uB124 \uC791\uAC00",
      prev: 0,
      icon: "\u{1F331}"
    };
  } else if (totalChars <= 15e3) {
    return {
      name: isEn ? "Neighborhood Writer \u2712\uFE0F" : "\uB3D9\uB124 \uC791\uAC00 \u2712\uFE0F",
      next: 15e3,
      nextName: isEn ? "Professional Writer" : "\uD504\uB85C \uC791\uAC00",
      prev: 5e3,
      icon: "\u2712\uFE0F"
    };
  } else if (totalChars <= 5e4) {
    return {
      name: isEn ? "Professional Writer \u{1FAB6}" : "\uD504\uB85C \uC791\uAC00 \u{1FAB6}",
      next: 5e4,
      nextName: isEn ? "Master Writer" : "\uAC70\uC7A5 \uC791\uAC00",
      prev: 15e3,
      icon: "\u{1FAB6}"
    };
  } else {
    return {
      name: isEn ? "Master Writer \u{1F451}" : "\uAC70\uC7A5 \uC791\uAC00 \u{1F451}",
      next: Infinity,
      nextName: "",
      prev: 5e4,
      icon: "\u{1F451}"
    };
  }
}
function translateAuthor(name) {
  if (typeof currentLang !== "undefined" && currentLang === "en") {
    const mapping = {
      "\uC774\uC0C1": "Yi Sang",
      "\uC724\uB3D9\uC8FC": "Yun Dong-ju",
      "\uAE40\uC720\uC815": "Kim Yu-jeong",
      "\uBC31\uC11D": "Baek Seok",
      "\uD55C\uC6A9\uC6B4": "Han Yong-un",
      "\uC815\uC9C0\uC6A9": "Jeong Ji-yong",
      "\uC870\uC9C0 \uC624\uC6F0": "George Orwell",
      "\uBC84\uC9C0\uB2C8\uC544 \uC6B8\uD504": "Virginia Woolf",
      "\uC5B4\uB2C8\uC2A4\uD2B8 \uD5E4\uBC0D\uC6E8\uC774": "Ernest Hemingway",
      "\uB098 (\uC791\uAC00)": "Me (Writer)"
    };
    return mapping[name] || name;
  }
  return name;
}
