let editingTargetProjectId = null;
function showEditBookDialogForProject(projectId) {
  const targetProj = projects.find((p) => p.id === projectId);
  if (!targetProj) return;
  editingTargetProjectId = projectId;
  editBookTitleInput.value = targetProj.title || "";
  let activeColor = targetProj.coverColor || "charcoal";
  if (activeColor.startsWith("#")) {
    activeColor = "charcoal";
  }
  dialogStates["edit-book"].color = activeColor;
  document.querySelectorAll("#edit-book-dialog .cover-color-picker .color-option").forEach((opt) => {
    opt.classList.remove("active");
  });
  const targetOpt = document.querySelector("#edit-book-dialog .cover-color-picker .color-option.".concat(activeColor));
  if (targetOpt) targetOpt.classList.add("active");
  const colorRadio = document.querySelector('#edit-book-dialog input[name="edit-cover-color"][value="'.concat(activeColor, '"]'));
  if (colorRadio) colorRadio.checked = true;
  const activeVisibility = targetProj.isPrivate ? "private" : "public";
  const visibilityRadio = document.querySelector('#edit-book-dialog input[name="edit-book-visibility"][value="'.concat(activeVisibility, '"]'));
  if (visibilityRadio) visibilityRadio.checked = true;
  updateDialogPreview("edit-book");
  editBookDialog.style.display = "flex";
  setTimeout(() => {
    editBookTitleInput.focus();
  }, 100);
}
function showEditBookDialog() {
  if (!project) return;
  showEditBookDialogForProject(project.id);
}
function hideEditBookDialog() {
  editBookDialog.style.display = "none";
  editingTargetProjectId = null;
}
